//! Upgrades block state ids and item ids that were saved by the Minecraft 1.20.4 version of the
//! server. The tables are generated by `mc_data/gen_upgrade_tables.py`.

use crate::plot_data::{ChunkData, PlotData};
use cinnabar_blocks::block_entities::BlockEntity;
use cinnabar_world::storage::{Chunk, ChunkSection};

static BLOCKS: &[u8] = include_bytes!("../../../mc_data/upgrade_blocks_1_20_4.bin");
static ITEMS: &[u8] = include_bytes!("../../../mc_data/upgrade_items_1_20_4.bin");

fn lookup(table: &[u8], id: u32) -> Option<u32> {
    let bytes = table.get(id as usize * 2..id as usize * 2 + 2)?;
    Some(u16::from_le_bytes([bytes[0], bytes[1]]) as u32)
}

/// The id of the block state in the current version. Unknown states become air.
pub fn upgrade_block_id(old: u32) -> u32 {
    lookup(BLOCKS, old).unwrap_or(0)
}

/// The id of the item in the current version, or `None` if the item doesn't exist anymore
pub fn upgrade_item_id(old: u32) -> Option<u32> {
    lookup(ITEMS, old).filter(|&id| id != 0xFFFF)
}

fn upgrade_chunk(chunk_data: ChunkData) -> ChunkData {
    let sections = chunk_data
        .sections
        .into_iter()
        .map(|section| {
            let Some(section) = section else {
                return ChunkSection::default();
            };
            let old = section.load();
            let mut new = ChunkSection::default();
            for y in 0..16 {
                for z in 0..16 {
                    for x in 0..16 {
                        let block = upgrade_block_id(old.get_block(x, y, z));
                        if block != 0 {
                            new.set_block(x, y, z, block);
                        }
                    }
                }
            }
            new
        })
        .collect();

    let mut block_entities = chunk_data.block_entities;
    for block_entity in block_entities.values_mut() {
        if let BlockEntity::Container { inventory, .. } = block_entity {
            inventory.retain_mut(|entry| match upgrade_item_id(entry.id) {
                Some(id) => {
                    entry.id = id;
                    true
                }
                None => false,
            });
        }
    }

    // The position of the chunk is not stored in the chunk data
    ChunkData::new(&mut Chunk::new(0, 0, sections, block_entities))
}

/// Upgrades all ids in a plot saved by the 1.20.4 version
pub fn upgrade_plot(data: PlotData) -> PlotData {
    PlotData {
        chunk_data: data.chunk_data.into_iter().map(upgrade_chunk).collect(),
        ..data
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn upgrades_block_ids() {
        // The repeater and comparator from the block id tests of 1.20.4 and 26.2
        assert_eq!(upgrade_block_id(5922), 7075);
        assert_eq!(upgrade_block_id(9186), 11274);
        assert_eq!(upgrade_block_id(0), 0);
    }

    #[test]
    fn upgrades_item_ids() {
        // minecraft:redstone
        assert_eq!(upgrade_item_id(0), Some(0));
        assert!(upgrade_item_id(10_000).is_none());
    }
}
